BEGIN;
CREATE TEMP TABLE evolution_base AS SELECT community_test.snapshot() value;
SET LOCAL ROLE authenticated;
SELECT community_test.actor(1);
SELECT public.save_server_community(community_test.id('a'),community_test.payload('a'),0);
SELECT community_test.assert(jsonb_array_length(public.get_community_cosmetics(community_test.id('a'))->'items')=5,'five implemented original render assets');
SELECT community_test.assert(public.get_community_cosmetics(community_test.id('a'))#>>'{equipped,seal}' IS NULL,'unlock does not auto-equip');
SELECT public.equip_community_cosmetic(community_test.id('a'),'seal','lx_foundation_seal',0);
SELECT community_test.assert(public.get_community_cosmetics(community_test.id('a'))#>>'{equipped,seal}'='foundation_seal','owner equips verified milestone');
SELECT community_test.denied($q$SELECT public.equip_community_cosmetic(community_test.id('a'),'theme','lx_orbit_theme',1)$q$,'42501','community_cosmetic_locked');
SELECT community_test.denied($q$SELECT public.equip_community_cosmetic(community_test.id('a'),'seal','lx_foundation_seal',0)$q$,'40001','revision');
SELECT community_test.denied($q$SELECT public.equip_community_cosmetic(community_test.id('a'),'theme','unknown',1)$q$,'42501','locked');
SELECT community_test.denied($q$SELECT public.equip_community_cosmetic(community_test.id('a'),'theme','lx_foundation_seal',1)$q$,'42501','locked');
SELECT public.set_community_role_permission(community_test.id('a'),community_test.id('delegate-role'),true);
SELECT community_test.actor(2);
SELECT public.equip_community_cosmetic(community_test.id('a'),'highlight','lx_lime_highlight',1);
SELECT community_test.assert(public.get_community_statistics(community_test.id('a'),current_date-7,current_date+1)->>'member_growth' IS NULL,'growth unavailable, never estimated');
SELECT community_test.actor(3);
SELECT community_test.denied($q$SELECT public.equip_community_cosmetic(community_test.id('a'),'seal',NULL,2)$q$,'42501','forbidden');
SELECT community_test.denied($q$SELECT public.get_community_statistics(community_test.id('a'),current_date-7,current_date+1)$q$,'42501');
SELECT community_test.actor(5);
SELECT community_test.assert((public.get_community_cosmetics(community_test.id('a'))->>'can_manage')='false','member reads effective identity only');
SELECT community_test.denied('SELECT * FROM public.community_cosmetic_selection','42501');
SELECT community_test.denied($q$SELECT public.get_community_statistics(community_test.id('a'),current_date-7,current_date+1)$q$,'42501');
SELECT community_test.actor(7);
SELECT community_test.denied($q$SELECT public.get_community_cosmetics(community_test.id('a'))$q$,'42501');
SELECT community_test.actor(1);
CREATE TEMP TABLE cosmetic_directory AS SELECT jsonb_build_object('name','Comunidade local','description','Publicação sintética para cosméticos.','icon_url',NULL,'banner_url',NULL,'category','gaming','language','pt-br','interests','[]'::jsonb,'public_rules','["Respeito."]'::jsonb,'admission','approval','consent',true) value;
SELECT public.save_community_discovery(community_test.id('a'),(SELECT value FROM cosmetic_directory),0,true);
CREATE TEMP TABLE original_appearance AS SELECT to_jsonb(s) value FROM public.servers s WHERE id=community_test.id('a');
SELECT public.equip_community_cosmetic(community_test.id('a'),'theme','lx_orbit_theme',2);
SELECT public.equip_community_cosmetic(community_test.id('a'),'banner','lx_grid_banner',3);
SELECT public.equip_community_cosmetic(community_test.id('a'),'theme',NULL,4);
SELECT public.equip_community_cosmetic(community_test.id('a'),'banner',NULL,5);
SELECT community_test.assert((SELECT value FROM original_appearance)=(SELECT to_jsonb(s) FROM public.servers s WHERE id=community_test.id('a')),'equip/remove never overwrites original theme/banner/server fields');
RESET ROLE;
-- Even a registered unlock cannot bypass disabled mission eligibility.
INSERT INTO public.community_reward_unlocks(server_id,reward_id,objective_id,version) VALUES(community_test.id('a'),'lx_orbit_frame','verified_weekly',1);
SET LOCAL ROLE authenticated;
SELECT community_test.actor(1);
SELECT community_test.denied($q$SELECT public.equip_community_cosmetic(community_test.id('a'),'frame','lx_orbit_frame',6)$q$,'42501','locked');
SELECT community_test.denied($q$SELECT public.get_community_statistics(community_test.id('a'),current_date-100,current_date+1)$q$,'22023');
RESET ROLE;
UPDATE security_private.community_xp_policy SET enabled=true;
INSERT INTO security_private.community_verified_activities VALUES('d4c00000-0000-0000-0000-000000000001',community_test.id('a'),'backend_verified_activity',gen_random_uuid(),clock_timestamp(),clock_timestamp()+interval '1 hour');
SELECT public.consume_verified_community_activity(community_test.id('a'),'d4c00000-0000-0000-0000-000000000001');
SELECT community_test.assert((public.get_community_statistics(community_test.id('a'),current_date-7,current_date+1)->>'xp_received')='100','statistics sum actual ledger');
SELECT community_test.assert(public.get_community_statistics(community_test.id('a'),current_date-7,current_date+1)#>>'{history,0,awarded_xp}'='100','bounded history from actual grants');
SELECT community_test.assert(public.get_community_statistics(community_test.id('a'),current_date-7,current_date+1)->>'events_realized' IS NULL,'scheduled never fabricated as realized');
INSERT INTO public.community_events(id,server_id,channel_id,title,starts_at,timezone) VALUES('d4c50000-0000-0000-0000-000000000001',community_test.id('a'),community_test.id('a-welcome'),'Evento sintético',clock_timestamp(),'UTC');
INSERT INTO public.community_event_rsvps(event_id,member_id,response) SELECT 'd4c50000-0000-0000-0000-000000000001',id,'going' FROM public.server_members WHERE server_id=community_test.id('a') AND user_id=community_test.user_id(5);
SELECT community_test.assert((public.get_community_statistics(community_test.id('a'),current_date-7,current_date+1)->>'events_created')='1','real event creation counted');
SELECT community_test.assert((public.get_community_statistics(community_test.id('a'),current_date-7,current_date+1)->>'rsvp_going')='1','RSVP counted only as intention');
SAVEPOINT statistics_privacy;
UPDATE public.roles SET permissions=permissions||'{"view_channel":false}' WHERE id=community_test.id('a-member-role');
SELECT community_test.actor(2);
SELECT community_test.assert((public.get_community_statistics(community_test.id('a'),current_date-7,current_date+1)->>'events_created')='0','delegated manager cannot infer inaccessible events');
SELECT community_test.assert((public.get_community_statistics(community_test.id('a'),current_date-7,current_date+1)->>'rsvp_going')='0','private event intentions remain private');
ROLLBACK TO SAVEPOINT statistics_privacy;
SAVEPOINT cosmetic_audit;
CREATE FUNCTION community_test.reject_cosmetic_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='community_cosmetic_changed' THEN RAISE EXCEPTION 'test_cosmetic_audit_failed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER reject_cosmetic_audit BEFORE INSERT ON public.audit_logs FOR EACH ROW EXECUTE FUNCTION community_test.reject_cosmetic_audit();
SELECT community_test.denied($q$SELECT public.equip_community_cosmetic(community_test.id('a'),'seal',NULL,6)$q$,'P0001','test_cosmetic_audit_failed');
SELECT community_test.assert((public.get_community_cosmetics(community_test.id('a'))->>'revision')='6','audit failure rolls back selection/revision');
ROLLBACK TO SAVEPOINT cosmetic_audit;
GRANT SELECT ON public.community_cosmetic_selection TO authenticated;
SET LOCAL ROLE authenticated;
SELECT community_test.actor(1);
SELECT community_test.assert(NOT EXISTS(SELECT FROM public.community_cosmetic_selection),'RLS blocks raw state even with SELECT grant');
SELECT public.set_community_role_permission(community_test.id('a'),community_test.id('delegate-role'),false);
SELECT community_test.actor(2);
SELECT community_test.denied($q$SELECT public.equip_community_cosmetic(community_test.id('a'),'seal',NULL,6)$q$,'42501');
SELECT community_test.actor(1);
SELECT public.disable_server_community(community_test.id('a'),1);
SELECT community_test.denied($q$SELECT public.get_community_cosmetics(community_test.id('a'))$q$,'42501');
SELECT public.save_server_community(community_test.id('a'),community_test.payload('a'),2);
SELECT community_test.assert(public.get_community_cosmetics(community_test.id('a'))#>>'{equipped,seal}'='foundation_seal','disable preserves identity selection/unlocks');
RESET ROLE;
SELECT community_test.assert(community_test.snapshot()->'xp'=(SELECT value->'xp' FROM evolution_base),'individual XP preserved');
SELECT community_test.assert(community_test.snapshot()->'messages'=(SELECT value->'messages' FROM evolution_base),'messages preserved');
ROLLBACK;
